function openMediaEditor(id){let e=E[id];if(!e)return;mediaExercise=id;const dialog=$('mediaDialog');$('mediaHeading').textContent=e.name;$('mediaMessage').textContent='';for(const type of ['image','video']){let r=userMedia.get(mediaKey(id,type));$('media-'+type+'-url').value=r?.url||'';$('media-'+type+'-file').value='';$('media-'+type+'-status').textContent=r?(r.blob?'Arquivo salvo: '+(r.name||'arquivo local'):'Link personalizado salvo'):'Demonstração padrão'}dialog.showModal()}
