document.addEventListener('click',ev=>{let b=ev.target.closest('[data-media-edit],[data-media-save],[data-media-reset],[data-media-close],[data-media-play]');if(!b)return;if(b.hasAttribute('data-media-play')){let src=videoEmbed(b.dataset.mediaPlay);if(!src)return;let frame=document.createElement('iframe');frame.src=src;frame.title=b.dataset.mediaTitle;frame.referrerPolicy='strict-origin-when-cross-origin';frame.allow='encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;b.replaceWith(frame)}else if(b.hasAttribute('data-media-edit'))openMediaEditor(Number(b.dataset.mediaEdit));else if(b.hasAttribute('data-media-save')){let [type,source]=b.dataset.mediaSave.split(':');saveMedia(type,source)}else if(b.hasAttribute('data-media-reset'))resetMedia(b.dataset.mediaReset);else $('mediaDialog').close()});


