function chooseDays(n){return ({2:[0,3],3:[0,2,4],4:[0,1,3,4],5:[0,1,2,3,4]})[n]||[0,2,4]}

function beginnerTemplate(n,mode){const home=mode==='casa',full=home?[[35,50,37,36,41],[40,50,37,42,39]]:[[43,6,45,3,13],[15,46,20,3,5]],upper=home?[50,37,53,41]:[6,45,46,48,12],lower=home?[35,36,40,42]:[43,3,15,5],easy=home?[39,53,54]:[13,26,5];let groups=n<=3?chooseDays(n).map((_,k)=>full[k%2]):n===4?[lower,upper,lower,upper]:[lower,upper,easy,lower,upper];return chooseDays(n).map((wd,k)=>{let light=n===5&&k===2;return {...emptyday(wd),title:light?'Core e recuperação':n>3?(groups[k]===lower?'Inferiores':'Superiores'):(home?'Calistenia':'Corpo inteiro')+' '+(k+1),warm:'Caminhada 5 min; agachamento sem carga 8; mobilidade de quadril 8/lado; mobilidade escapular 10.',cardio:light?'Caminhada leve 15 min, se confortável.':'Opcional: caminhada leve 10 min, conforme recuperação.',ex:groups[k].map(id=>({...copy(E[id]),sets:light?1:2,rir:light?'4':'3',special:'',warm:1}))}})}
function planShape(p){return JSON.stringify(p?.days.map(d=>[d.name,d.ex.map(e=>[e.id,e.sets])])||[])}
function validDraft(p){try{unpack(sharePayload(p));return true}catch{return false}}
function dataDownload(){const payload={version:1,exportedAt:new Date().toISOString(),plans:S.plans,checks:S.checks,entries:S.entries,logs:S.logs,notes:S.notes,active:S.plan};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='traincore-backup-'+date()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Cópia dos dados exportada. Guarde o arquivo em local seguro.')}

function readBackup(b){if(!b||b.version!==1||!Array.isArray(b.plans)||b.plans.length>100)throw Error('Arquivo de backup incompatível.');const ids=new Set();let plans=b.plans.map(p=>{if(!p||typeof p.id!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(p.id)||ids.has(p.id))throw Error('Identificador de treino inválido.');ids.add(p.id);return {...unpack(sharePayload(p)),id:p.id}});const object=x=>x&&typeof x==='object'&&!Array.isArray(x)?x:{};const belongs=k=>{const parts=k.split(':');return parts.length>=3&&ids.has(parts[1])};let checks=Object.fromEntries(Object.entries(object(b.checks)).filter(([k,v])=>belongs(k)&&typeof v==='boolean').slice(0,100000)),entries=Object.fromEntries(Object.entries(object(b.entries)).filter(([k,v])=>belongs(k)&&v&&typeof v==='object').slice(0,100000).map(([k,v])=>[k,{load:String(v.load||'').slice(0,12),actual:String(v.actual||'').slice(0,20)}])),notes=Object.fromEntries(Object.entries(object(b.notes)).filter(([k,v])=>ids.has(k.split(':')[0])&&typeof v==='string').slice(0,2000).map(([k,v])=>[k,v.slice(0,20000)]));const logs=Array.isArray(b.logs)?b.logs.filter(l=>l&&typeof l.plan==='string'&&typeof l.day==='string'&&typeof l.date==='string'&&typeof l.id==='string'&&Number.isFinite(l.done)&&Number.isFinite(l.total)).slice(-3000).map(l=>({id:l.id.slice(0,200),plan:l.plan.slice(0,120),day:l.day.slice(0,80),date:l.date.slice(0,20),done:Math.max(0,l.done),total:Math.max(0,l.total),note:String(l.note||'').slice(0,20000),exercises:Array.isArray(l.exercises)?l.exercises.filter(e=>e&&typeof e.name==='string'&&Number.isFinite(e.done)&&Number.isFinite(e.total)).slice(0,40).map(e=>({name:e.name.slice(0,160),done:e.done,total:e.total,records:Array.isArray(e.records)?e.records.filter(r=>r&&Number.isInteger(r.set)).slice(0,10).map(r=>({set:r.set,load:String(r.load||'').slice(0,12),actual:String(r.actual||'').slice(0,20)})):[]})):[]})):[];return {plans,checks,entries,logs,notes,plan:ids.has(b.active)?b.active:plans[0]?.id||null}}
async function restoreBackup(file){if(!file)return;try{if(file.size>8*1024*1024)throw Error('Arquivo de backup muito grande.');let p=readBackup(JSON.parse(await file.text()));if(!confirm('Importar '+p.plans.length+' treino(s) e '+p.logs.length+' registro(s)? Os dados de treino atuais deste navegador serão substituídos.'))return;stopRest();Object.assign(S,p);S.day=0;draft=null;S.tab='home';render(false);toast('Cópia importada com sucesso.')}catch(e){alert(e.message||'Não foi possível importar a cópia.')}} 
document.addEventListener('change',ev=>{if(ev.target.id==='restoreFile'){const file=ev.target.files?.[0];ev.target.value='';restoreBackup(file)}});

function dayOptions(name){return weekdays.map(w=>'<option value="'+w+'" '+(norm(name).replace(/feira$/,'')===norm(w)?'selected':'')+'>'+w+'</option>').join('')+(!weekdays.some(w=>norm(name).replace(/feira$/,'')===norm(w))?'<option selected value="'+esc(name)+'">'+esc(name)+'</option>':'')}
function savedOpen(){return Array.from(document.querySelectorAll('details[data-persist-open][open]')).map(el=>el.dataset.persistOpen)}



function hero(p){const today=todaysIndex(p),has=!!p.id,day=today>=0?p.days[today]:null;return '<section class="hero"><div><span class="eyebrow">'+esc(new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'}))+'</span><h1>'+(has?(day?esc(day.title):'Dia de descanso'):'Seu treino, do começo ao fim.')+'</h1><p>'+(has?(day?esc(p.name)+' · '+day.ex.length+' exercícios':'Nenhuma sessão agendada para hoje.'):'Crie uma ficha de musculação ou calistenia, acompanhe suas séries e consulte a execução dos movimentos.')+'</p><div class="actions"><button class="btn primary" data-a="'+(has?(day?'day':'tab'):'new')+'" data-v="'+(day?today:'train')+'">'+(has?(day?'Iniciar treino':'Ver ficha'):'Criar ficha')+'</button>'+(!has?'<button class="btn" data-share="import">Importar</button>':'')+'</div></div><figure class="hero-visual"><img src="https://images.pexels.com/photos/6390238/pexels-photo-6390238.jpeg?auto=compress&dpr=1&h=750&w=1260" alt="Atleta treinando com barra na academia" onerror="this.hidden=true"><figcaption><a href="https://www.pexels.com/photo/a-woman-holding-a-barbell-while-standing-in-the-gym-6390238/" target="_blank" rel="noopener noreferrer">Foto: Tima Miroshnichenko / Pexels</a></figcaption></figure></section>'}
function weeklyCalendar(p){const now=(new Date().getDay()+6)%7;return '<section class="panel dashboard-week"><div class="section" style="margin:0"><h2>Minha semana</h2><small>'+esc(weekText())+'</small></div><div class="weekly-days">'+weekdays.map((w,i)=>{const d=p.days.findIndex(x=>norm(x.name).replace(/feira$/,'')===norm(w)),has=d>=0,done=has&&count(p,d)===sum(p.days[d])&&sum(p.days[d])>0;return '<'+(has?'button':'div')+' class="weekly-day '+(i===now?'current ':'')+(has?'planned ':'')+(done?'completed':'')+'" '+(has?'data-a="day" data-v="'+d+'" aria-label="Abrir '+esc(w)+'"':'')+'><strong>'+esc(w.slice(0,3))+'</strong><span class="day-dot"></span><small>'+(done?'Feito':has?'Treino':p.id?'Descanso':'—')+'</small></'+(has?'button':'div')+'>'}).join('')+'</div></section>'}
function dashboardLinks(){return '<section class="dashboard-links" aria-label="Assistentes"><button class="tool-link" data-a="tab" data-v="coach"><span>Assistente de treino<small>Montar ou ajustar uma ficha com IA</small></span><span aria-hidden="true">›</span></button><button class="tool-link" data-a="tab" data-v="food"><span>Assistente de nutrição<small>Consultar sugestões de refeições com IA</small></span><span aria-hidden="true">›</span></button></section>'}
function home(){let p=active(),c=complete(p),t=total(p);return hero(p)+'<div class="grid home-metrics"><div class="panel stat"><small>Séries concluídas</small><strong>'+(t?c+'/'+t:'—')+'</strong>'+bar(c,t)+'</div><div class="panel stat"><small>Treinos completos</small><strong>'+(p.days.length?p.days.filter((d,i)=>sum(d)>0&&count(p,i)===sum(d)).length+'/'+p.days.length:'—')+'</strong></div><div class="panel stat"><small>Sessões no histórico</small><strong>'+S.logs.length+'</strong></div></div>'+weeklyCalendar(p)+'<div class="split"><section class="panel home-plan"><div class="section" style="margin:0 0 12px"><div><h2>'+esc(p.name)+'</h2></div><button class="mini" data-a="tab" data-v="plans">Meus planos</button></div>'+(!p.id?'<div class="empty-state"><p>Nenhuma ficha selecionada.</p></div>':'')+p.days.map((d,i)=>'<div class="row"><div><h3>'+esc(d.name)+'</h3><small>'+esc(d.title)+' · '+d.ex.length+' exercícios</small></div><button class="btn" data-a="day" data-v="'+i+'" aria-label="Abrir treino de '+esc(d.name)+'">'+count(p,i)+'/'+sum(d)+' ›</button></div>').join('')+recoveryDays(p)+'</section><div class="dashboard-secondary"><section class="panel library-promo"><img loading="lazy" src="https://images.pexels.com/photos/4164766/pexels-photo-4164766.jpeg?auto=compress&cs=tinysrgb&w=640" alt="Halteres na academia" onerror="this.hidden=true"><div><h2>Biblioteca de exercícios</h2><p>'+E.length+' movimentos de academia e calistenia.</p><button class="btn" data-a="tab" data-v="library">Ver exercícios</button><div class="photo-credit"><a href="https://www.pexels.com/photo/silver-dumbbells-on-black-steel-rack-4164766/" target="_blank" rel="noopener noreferrer">Foto: Ivan S / Pexels</a></div></div></section>'+dashboardLinks()+'</div></div><section class="panel"><h2>Histórico de sessões</h2>'+historyMarkup()+'</section><section class="panel data-section"><h2>Seus dados</h2><p>Os treinos, cargas e histórico ficam neste navegador. Faça uma cópia para transferir para outro dispositivo ou endereço do Traincore.</p><div class="actions"><button class="btn" data-a="backup">Exportar dados</button><button class="btn" data-a="restore">Importar cópia</button></div><input type="file" id="restoreFile" accept="application/json,.json"><p class="file-help">A importação substitui os dados de treino neste aparelho.</p></section>'}
