function warmAmount(text,fallback){text=text.replace(/[.!?]+$/,'').trim();let m=text.match(/(\d+(?:[–-]\d+)?)\s*(?:min(?:utos?)?)/i);if(m)return m[1]+' minutos leves';m=text.match(/(\d+(?:[–-]\d+)?)\s*(?:repetições|reps)?\s*(?:\/\s*(?:lado|perna|braço)|por\s+(?:lado|perna|braço))/i);if(m)return m[1]+' repetições por lado';m=text.match(/(\d+(?:[–-]\d+)?)\s*(?:repetições|reps)?\s*$/i);if(m)return m[1]+' repetições'+(/por braço/.test(fallback)?' por braço':'');return fallback}
function warmVisual(e){let out='';if(e.image){out='<div class="warm-poses"><figure>'+mediaImage(photoURL(e.image),e)+'<figcaption>'+(e.second?'Posição inicial':'Referência visual')+'</figcaption></figure>'+(e.second?'<figure>'+mediaImage(photoURL(e.second),e)+'<figcaption>Posição final</figcaption></figure>':'')+'</div><p class="microcopy"><a href="https://repdb.co/" target="_blank" rel="noopener noreferrer">Exercise data by RepDB (repdb.co)</a></p>'}if(e.video)out+='<video class="warm-video" controls playsinline preload="none" src="'+esc(workoutVideoBase+e.video+'.mp4')+'" onerror="this.parentElement.classList.add(\'media-failed\')"></video><p class="microcopy">Vídeo: <a href="https://github.com/namnq/workout-free-videos" target="_blank" rel="noopener noreferrer">Workout Free Videos (CC0)</a></p>';if(e.external)out+='<p><a class="btn" href="'+esc(e.external)+'" target="_blank" rel="noopener noreferrer">Ver demonstração externa</a></p>'+(e.externalNote?'<p class="microcopy">'+esc(e.externalNote)+'</p>':'');if(e.variant)out+='<p class="microcopy">'+esc(e.variant)+'</p>';return out?'<div class="warm-reference">'+out+'</div>':'<p class="microcopy">Ainda não há demonstração licenciada desta execução no catálogo. Use as instruções e o link de vídeo abaixo.</p>'}
function warmGuide(d){const raw=String(d.warm||'').trim();if(!raw)return '<p>Nenhum aquecimento foi especificado nesta ficha. Prepare-se com movimentos leves e adequados ao treino; se tiver dúvida, consulte um profissional.</p>';const items=raw.split(/[;\n•]+/).map(t=>t.trim()).filter(Boolean);const steps=items.map(t=>{const n=norm(t);let i=/ponte/.test(n)?11:/deadbug/.test(n)?12:/afundo|passada/.test(n)?10:/stiff|romeno/.test(n)?5:warmExamples.findIndex(e=>e.re.test(n));if(i<0&&/^(?:\d+)min/.test(n))i=2;const e=warmExamples[i];if(!e)return {name:t,amount:'Conforme a ficha',how:'Consulte a instrução original e confirme a execução antes de tentar um movimento desconhecido.',q:t+' execução aquecimento',original:t};return {...e,...warmMedia[i],amount:warmAmount(t,e.amount),original:t}});return '<p class="explain">O aquecimento prepara os movimentos da sessão sem gastar a energia das séries principais. Faça com esforço leve e sem dor.</p><div class="warm-steps">'+steps.map((e,i)=>{const m=e.original.match(/(\d+)\s*min/i),sec=m?Number(m[1])*60:0;return '<article class="warm-step"><div class="warm-step-top"><span class="warm-step-number">'+(i+1)+'</span><div><h4>'+esc(e.name)+'</h4><span class="warm-amount">'+esc(e.amount)+'</span></div></div><div class="warm-instructions"><p><strong>Como fazer:</strong> '+esc(e.how)+'</p>'+(e.why?'<p><strong>Por que fazer:</strong> '+esc(e.why)+'</p>':'')+(e.load?'<p><strong>Carga:</strong> '+esc(e.load)+'</p>':'')+'</div>'+warmVisual(e)+(sec>0?'<button class="btn" data-a="timer" data-v="'+Math.min(sec,3600)+'" data-rest-kind="Aquecimento" data-rest-name="'+esc(e.name)+'">Cronometrar '+esc(restWords(sec))+'</button>':'')+'<a class="warm-search" target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/results?search_query='+encodeURIComponent(e.q)+'">Buscar vídeo de execução</a></article>'}).join('')+'</div><details class="warm-specific"><summary>Prescrição original da ficha</summary><p>'+esc(raw)+'</p></details>'}
function warmSpecific(e){let n=Number(e.warm)||0;if(!n)return '<p class="set-explain">Não há séries de aquecimento específicas prescritas. Se precisar, ensaie o movimento com resistência leve antes das séries principais.</p>';let reps=n===1?['8–12']:n===2?['10','5–6']:['12','8','4–5',...Array(Math.max(0,n-3)).fill('3–5')];return '<details class="warm-specific" open data-persist-open="warm:'+esc(e.id)+'"><summary>'+n+' '+(n===1?'série preparatória':'séries preparatórias')+' (aquecimento)</summary><p><strong>Objetivo:</strong> praticar '+esc(e.name)+' e preparar os músculos antes de aumentar o esforço. As séries preparatórias não contam nas séries principais.</p><p><strong>Qual carga usar?</strong> Se o movimento permitir, comece sem peso adicional ou com a menor resistência confortável. A barra vazia também tem peso; use uma alternativa mais leve se necessário. Nas séries seguintes, aumente aos poucos somente se a técnica estiver firme. Evite a fadiga.</p><div class="warm-series-list">'+reps.slice(0,n).map((r,i)=>'<div><strong>Aquecimento '+(i+1)+'</strong><span>'+r+' repetições</span><small>'+(i===0?'Resistência muito leve.':'Resistência leve, sem chegar perto da falha.')+'</small></div>').join('')+'</div><p>Termine sentindo que ainda poderia fazer pelo menos 4 repetições. A pausa entre aquecimentos sugerida nesta ficha é de 60 segundos; para compostos exigentes, 90 segundos antes da série principal.</p><div class="warm-timer-actions"><button class="mini" data-a="timer" data-v="60" data-rest-kind="Aquecimento" data-rest-name="'+esc(e.name)+'">Descanso 1 min</button><button class="mini" data-a="timer" data-v="90" data-rest-kind="Aquecimento antes das séries principais" data-rest-name="'+esc(e.name)+'">Descanso 1 min 30 s</button></div><p class="microcopy">A demonstração do mesmo movimento está logo abaixo nas instruções de execução. Para aquecer, use a resistência leve descrita acima, não necessariamente a carga da demonstração.</p></details>'}
function repsLabel(e){let r=String(e.reps||'');if(/\d\s*(?:s|seg(?:undos)?|min(?:utos?)?)\b/i.test(r))return r.replace(/(\d)\s*s\b/g,'$1 segundos').replace(/\/(lado|perna|braço)/g,' por $1');return r.replace(/\/(lado|perna|braço)/g,' por $1').replace(/^(\d+(?:[–-]\d+)?)(?=\s+por\b)/,'$1 repetições').replace(/^(\d+(?:[–-]\d+)?)$/,'$1 repetições')}
function reserveFor(e,i){let parts=String(e.rir||'').split('/').map(x=>x.trim());return parts.length===e.sets?parts[i]:String(e.rir||'').trim()}
function reserveLabel(e,i){const r=reserveFor(e,i);if(/^\d+(?:[–-]\d+)?$/.test(r))return r+' em reserva';return r?'RIR '+r:''}
function terms(){return '<dl class="term-box"><dt>Série</dt><dd>Um bloco de repetições. Ex.: 3 séries de 10 significa executar 10 movimentos, descansar e repetir o bloco mais duas vezes.</dd><dt>Repetição</dt><dd>Um movimento completo, com subida e descida controladas. Quando indicado por lado, faça em ambos os lados.</dd><dt>RIR — repetições em reserva</dt><dd>Quantas repetições ainda conseguiria fazer mantendo a técnica. RIR 2 significa parar com aproximadamente 2 repetições possíveis; RIR 0 é falha técnica. Os números em sequência correspondem às séries na ordem.</dd><dt>Descanso</dt><dd>Intervalo entre séries principais. Em exercícios unilaterais, troque de lado em aproximadamente 20 segundos e conte o descanso após os dois lados.</dd><dt>Cadência</dt><dd>Tempo de cada fase do movimento: subida, descida e pausas. Ex.: descer em 3 segundos e subir em 1 segundo.</dd><dt>Drop-set e rest-pause</dt><dd>Drop-set é reduzir a resistência e continuar; rest-pause é fazer pausas curtas e continuar com a mesma resistência. Faça somente se prescritos, na série indicada.</dd></dl>'}


function restFormat(sec){sec=Math.max(0,Math.ceil(Number(sec)||0));return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}
function restWords(sec){sec=Math.max(0,Math.ceil(Number(sec)||0));let m=Math.floor(sec/60),r=sec%60;return [m?m+(m===1?' minuto':' minutos'):'',r?r+(r===1?' segundo':' segundos'):''].filter(Boolean).join(' e ')||'0 segundos'}
function restKey(p,d,i){return p.id+':'+d+':'+i}
function restPanel(e,p,i){const k=restKey(p,S.day,i),n=Math.max(0,Number(e.rest)||0);return '<div class="rest-panel" data-rest-key="'+esc(k)+'"><div class="rest-top"><div><div class="rest-title">Descanso entre séries</div><p>Intervalo previsto: '+esc(restWords(n))+'</p></div><div><div class="rest-value" data-rest-value>'+restFormat(n)+'</div><div class="rest-inline-state" data-rest-state>Tempo previsto</div></div></div><p>Nos exercícios por lado, conclua os dois lados antes do descanso.</p><button class="btn primary" data-a="timer" data-v="'+n+'" data-rest-name="'+esc(e.name)+'" data-rest-owner="'+esc(k)+'" data-rest-kind="Séries principais">Iniciar cronômetro · '+restFormat(n)+'</button></div>'}
function restSetting(){return '<div class="rest-setting"><div><label for="autoRest"><input id="autoRest" type="checkbox" '+(S.autoRest!==false?'checked':'')+'> Iniciar descanso automaticamente</label><small>Ao marcar uma série como concluída, o cronômetro usa o intervalo indicado no exercício. Desative se preferir iniciar manualmente.</small></div></div>'}
function recoveryDays(p){const names=['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'],dayNorm=x=>norm(x).replace(/feira$/,'');let used=p.days.map(d=>dayNorm(d.name));if(!used.length||used.some(x=>!names.some(n=>dayNorm(n)===x)))return '';let rest=names.filter(n=>!used.includes(dayNorm(n)));return rest.length?'<div class="recovery-note"><strong>Dias sem treino nesta ficha: '+esc(rest.join(' e '))+'.</strong><p>Use esses dias para recuperação; caminhada leve ou mobilidade são opcionais, conforme sua disposição.</p></div>':''}

function exerciseExplanation(e){let r=String(e.reps||''),m=r.match(/^(\d+)(?:[–-](\d+))?/),timed=/\d\s*(?:s|seg(?:undos)?|min(?:utos?)?)\b/i.test(r),unilateral=/\/(?:lado|perna|braço)|por (?:lado|perna|braço)/i.test(r),example=timed?'Mantenha o movimento ou a posição pelo tempo indicado.':m?'Faça '+esc(m[1])+(m[2]?' a '+esc(m[2]):'')+' repetições'+(unilateral?' de cada lado':'')+' antes de descansar.':'Complete o bloco indicado antes de descansar.';let bw=e.mode==='casa'||/sem carga|peso corporal|peso do corpo/i.test(e.equip||'');return '<div class="exercise-understand"><div><strong>O que fazer</strong><p>'+esc(e.sets)+' '+(e.sets===1?'série':'séries')+' de '+esc(repsLabel(e))+'. '+example+' Repita até completar o número de séries.</p></div><div><strong>Por que essa quantidade?</strong><p>As séries distribuem o trabalho em blocos com recuperação. As repetições definem a duração do esforço de cada bloco. A quantidade foi definida pela ficha; não é uma regra universal.</p></div><div><strong>Como escolher a carga</strong><p>'+(bw?'Comece com o peso do corpo ou a resistência prescrita, adaptando a dificuldade para manter a técnica.':'Escolha uma resistência que permita cumprir as repetições com técnica e respeitar as repetições em reserva. Sem carga definida na ficha não significa que a série principal deva ser feita sem peso.')+'</p></div><div><strong>Quando parar</strong><p>RIR '+esc(e.rir||'não definido')+'. RIR 2, por exemplo, significa terminar a série sabendo que ainda conseguiria aproximadamente 2 repetições com boa técnica. Pare se perder o controle ou sentir dor aguda.</p></div></div>'}
function exerciseIndex(d){return '<details class="workout-index"><summary>Índice de exercícios</summary><label class="label" for="workoutSearch">Encontrar exercício nesta sessão</label><input id="workoutSearch" type="search" placeholder="Nome, músculo ou equipamento"><div id="workoutIndexList">'+d.ex.map((e,i)=>'<button class="workout-jump" data-a="jump-ex" data-v="'+i+'" data-search="'+esc(norm(e.name+' '+e.muscle+' '+e.equip))+'"><span class="jump-num">'+(i+1)+'</span><span>'+esc(e.name)+'<small>'+e.sets+' séries · '+esc(e.muscle)+'</small></span><span class="jump-arrow" aria-hidden="true"></span></button>').join('')+'</div><p id="workoutNoResults" hidden>Nenhum exercício encontrado nesta sessão.</p></details>'}
function sessionFocus(p,d){const i=d.ex.findIndex((e,i)=>Array.from({length:e.sets},(_,j)=>!checked(p.id,S.day,i,j)).some(Boolean));if(i<0)return '<section class="session-focus"><div><h3>Séries principais concluídas</h3><p>Confira os complementos e registre a sessão.</p></div></section>';const e=d.ex[i],next=d.ex.slice(i+1).find((x,j)=>Array.from({length:x.sets},(_,s)=>!checked(p.id,S.day,i+j+1,s)).some(Boolean));return '<section class="session-focus"><div class="focus-image">'+thumb(e)+'</div><div><small>Próximo exercício pendente · '+(i+1)+' de '+d.ex.length+'</small><h3>'+esc(e.name)+'</h3><p>'+e.sets+' séries · '+esc(repsLabel(e))+' · '+restFormat(e.rest)+' de descanso</p>'+(next?'<small>Depois: '+esc(next.name)+'</small>':'')+'</div><button class="btn primary" data-a="jump-ex" data-v="'+i+'">Ir ao exercício</button></section>'}
function train(){let p=active();if(!p.id)return '<h1>Seu próximo treino</h1><section class="panel"><h2>Nenhum plano ativo</h2><p>Crie uma ficha, peça ajuda à IA ou importe um código recebido para começar. Seus treinos ficam salvos neste aparelho.</p><div class="actions" style="margin-top:12px"><button class="btn primary" data-a="new">Criar treino</button><button class="btn" data-share="import">Importar por código</button><button class="btn" data-a="tab" data-v="plans">Meus planos</button></div></section>';S.day=Math.max(0,Math.min(S.day,p.days.length-1));let d=p.days[S.day],c=count(p,S.day),t=sum(d);return '<details class="introhelp"><summary><strong>Como registrar um treino</strong></summary><p>Escolha o dia, faça o aquecimento e execute os exercícios na ordem. Toque em Série 1, Série 2 e assim por diante depois de completar cada bloco de repetições. O cronômetro de descanso inicia automaticamente ao marcar uma série, se a opção estiver ativada. Você também pode iniciá-lo manualmente. As orientações e demonstrações aparecem em cada exercício. Você pode recolhê-las quando quiser. Finalizar treino registra a sessão no histórico.</p></details><h1>'+esc(p.name)+'</h1><button class="btn" style="margin-top:12px" data-share="export" data-id="'+esc(p.id)+'">Compartilhar treino</button><div class="days">'+p.days.map((v,i)=>'<button class="day '+(i===S.day?'active':'')+'" data-a="day" data-v="'+i+'">'+esc(v.name.slice(0,3))+'<small>'+count(p,i)+'/'+sum(v)+'</small></button>').join('')+'</div><div class="section"><h2>'+esc(d.title)+'</h2><small>'+c+'/'+t+' séries</small></div>'+bar(c,t)+sessionFocus(p,d)+exerciseIndex(d)+restSetting()+recoveryDays(p)+'<div class="split"><div><section class="panel"><h3>Aquecimento e mobilidade</h3>'+warmGuide(d)+'<button class="mini '+(S.checks[key(p.id,S.day,'warm',0)]?'checked':'')+'" data-a="flag" data-v="warm">'+(S.checks[key(p.id,S.day,'warm',0)]?'Aquecimento concluído':'Concluir aquecimento e mobilidade')+'</button></section>'+d.ex.map((e,i)=>{let done=Array.from({length:e.sets},(_,s)=>checked(p.id,S.day,i,s)).every(Boolean),k=p.id+':'+S.day+':'+i;return '<article id="workout-ex-'+i+'" class="ex '+(done?'finished':'')+'"><div class="exhead"><div class="thumb">'+thumb(e)+'</div><div><small>Exercício '+(i+1)+'</small><h3>'+esc(e.name)+'</h3><div class="exercise-meta"><span>'+e.sets+' séries de '+esc(repsLabel(e))+'</span><span>· '+esc(restWords(e.rest))+' de descanso</span></div></div><button class="check '+(done?'checked':'')+'" aria-label="Marcar todas as séries" data-a="all" data-v="'+i+'" aria-pressed="'+done+'">'+(done?'<b class="check-mark" aria-hidden="true"></b><small>Concluído</small>':'<b class="check-empty" aria-hidden="true"></b><small>Marcar todas</small>')+'</button></div><div class="exbody"><details class="exercise-guidance"><summary>Orientações de carga, técnica e aquecimento</summary>'+exerciseExplanation(e)+warmSpecific(e)+'</details><div class="set-area"><strong>Séries principais</strong><p class="set-explain">Marque a série após concluí-la.</p><div class="sets">'+Array.from({length:e.sets},(_,s)=>'<button class="set '+(checked(p.id,S.day,i,s)?'checked':'')+'" data-a="set" data-v="'+i+':'+s+'" aria-pressed="'+checked(p.id,S.day,i,s)+'" aria-label="Série '+(s+1)+'">'+(checked(p.id,S.day,i,s)?'Série ':'Série ')+(s+1)+'<span class="set-rir">'+esc(reserveLabel(e,s))+'</span><span class="set-status">'+(checked(p.id,S.day,i,s)?'Concluída':'Pendente')+'</span></button>').join('')+'</div></div>'+setLog(e,p,i)+restPanel(e,p,i)+'<div class="actions"><button class="btn" data-a="detail" aria-expanded="'+open.has(k)+'" data-v="'+esc(k)+'">'+(open.has(k)?'Recolher execução':'Ver execução')+'</button></div>'+(e.special?'<div class="tech">'+esc(e.special)+(/rest.?pause/i.test(e.special)?'<div class="warm-timer-actions"><button class="mini" data-a="timer" data-v="20" data-rest-kind="Rest-pause" data-rest-name="'+esc(e.name)+'">Cronômetro da pausa de 20 s</button></div>':'')+'</div>':'')+'</div>'+(open.has(k)?'<div class="details exercise-expanded">'+details(e)+'</div>':'')+'</article>'}).join('')+'</div><aside><section class="panel"><h3>Cardio</h3><p>'+esc(d.cardio||'Nenhum cardio obrigatório neste treino.')+'</p>'+(d.cardio&&!/^sem cardio/i.test(d.cardio)?'<button class="mini '+(S.checks[key(p.id,S.day,'cardio',0)]?'checked':'')+'" data-a="flag" data-v="cardio">'+(S.checks[key(p.id,S.day,'cardio',0)]?'Cardio concluído':'Marcar cardio concluído')+'</button>':'')+'</section><section class="panel"><h3>Notas e cargas</h3><p class="explain">Registre pesos usados, dificuldades ou observações. São privadas neste navegador e não acompanham o código de compartilhamento.</p><textarea id="notes" aria-label="Notas e cargas da sessão" placeholder="Anote as cargas, sensações e repetições…">'+esc(S.notes[p.id+':'+S.day]||'')+'</textarea></section><section class="panel"><h3>Concluir sessão</h3><p>Salva o número de séries realizadas hoje. Você também pode registrar um treino parcial. As marcações da semana continuam visíveis.</p><button class="btn primary" data-a="finish" style="margin-top:10px">Finalizar treino</button></section><section class="panel"><h3>Entenda os termos da ficha</h3>'+terms()+'</section></aside></div>'}
function plans(){return '<details class="introhelp"><summary><strong>Como organizar seus treinos</strong></summary><p>Um plano reúne os dias de treino da semana. Escolha Usar para torná-lo ativo, Editar para alterar sua rotina, Duplicar para criar uma cópia ou Compartilhar para enviar a ficha a alguém.</p></details><div class="section"><h1>Meus planos</h1><button class="btn primary" data-a="new">Novo plano</button></div><section class="panel"><h2>Recebeu um treino?</h2><p>Cole um código para conferir a ficha e salvar sua própria cópia.</p><button class="btn" data-share="import" style="margin-top:10px">Importar por código</button></section>'+(!S.plans.length?'<section class="panel"><h2>Nenhuma ficha criada</h2><p>Crie uma ficha para montar sua rotina.</p></section>':'')+S.plans.map(p=>'<section class="panel plan-card"><div class="row"><div><h3>'+esc(p.name)+'</h3><small>'+p.days.length+' dias · '+total(p)+' séries</small></div>'+(S.plan===p.id?'<span class="tag">Ativo</span>':'')+'</div><div class="actions"><button class="btn primary" data-a="activate" data-v="'+p.id+'">Usar</button><button class="btn" data-a="edit" data-v="'+p.id+'">Editar</button><button class="btn" data-a="clone" data-v="'+p.id+'">Duplicar</button><button class="btn" data-share="export" data-id="'+esc(p.id)+'">Compartilhar</button><button class="btn danger" data-a="delete" data-v="'+p.id+'">Excluir</button></div></section>').join('')+(draft?builder():'')}
function editorOptions(q){const items=E.filter(e=>norm(e.name+' '+e.muscle+' '+e.equip+' '+e.alt).includes(norm(q))).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));return items.length?items.map(e=>'<option value="'+e.id+'">'+esc(e.name)+'</option>').join(''):'<option value="" disabled selected>Nenhum exercício encontrado</option>'}
function builder(){return '<section class="panel" id="builder"><h2>Editor de plano</h2><p class="explain">Escolha os dias e adicione os exercícios. Ajuste séries, repetições, descanso e repetições em reserva (RIR).</p><label class="label" for="pname">Nome</label><input id="pname" value="'+esc(draft.name)+'"><div class="formgrid"><div><label class="label" for="model">Modelo</label><select id="model"><option value="casa">Calistenia</option><option value="academia">Academia</option></select></div><div><label class="label" for="freq">Dias por semana</label><select id="freq"><option>2</option><option selected>3</option><option>4</option><option>5</option></select></div></div><button class="btn" data-a="generate" style="margin-top:10px">Gerar modelo introdutório</button><p class="note" style="margin-top:10px">Modelo introdutório, com dias de recuperação distribuídos. Para uma ficha adaptada ao seu nível e objetivo, converse com a IA. Você também pode editar manualmente.</p>'+draft.days.map((d,i)=>'<details class="editor-day" data-persist-open="editor:'+i+'" open><summary>Dia '+(i+1)+' · '+esc(d.name)+' — '+esc(d.title)+'</summary><label class="label" for="dayname'+i+'">Dia da semana</label><select id="dayname'+i+'" data-field="name" data-i="'+i+'">'+dayOptions(d.name)+'</select><label class="label" for="daytitle'+i+'">Nome do treino</label><input id="daytitle'+i+'" data-field="daytitle" data-i="'+i+'" value="'+esc(d.title)+'"><label class="label" for="daywarm'+i+'">Aquecimento</label><input id="daywarm'+i+'" data-field="warm" data-i="'+i+'" value="'+esc(d.warm||'')+'"><label class="label" for="daycardio'+i+'">Cardio / complemento</label><input id="daycardio'+i+'" data-field="cardio" data-i="'+i+'" value="'+esc(d.cardio||'')+'">'+d.ex.map((e,j)=>'<div class="editor-ex"><h3>'+esc(e.name)+'</h3><div class="formgrid"><div><label class="label" for="sets-'+i+'-'+j+'">Séries principais</label><input id="sets-'+i+'-'+j+'" type="number" min="1" max="10" data-field="sets" data-i="'+i+'" data-j="'+j+'" value="'+e.sets+'"></div><div><label class="label" for="reps-'+i+'-'+j+'">Repetições ou tempo</label><input id="reps-'+i+'-'+j+'" data-field="reps" data-i="'+i+'" data-j="'+j+'" value="'+esc(e.reps)+'"></div><div><label class="label" for="rest-'+i+'-'+j+'">Descanso (s)</label><input id="rest-'+i+'-'+j+'" type="number" min="15" max="600" data-field="rest" data-i="'+i+'" data-j="'+j+'" value="'+e.rest+'"></div><div><label class="label" for="rir-'+i+'-'+j+'">RIR (repetições em reserva)</label><input id="rir-'+i+'-'+j+'" data-field="rir" data-i="'+i+'" data-j="'+j+'" value="'+esc(e.rir)+'"></div></div><label class="label" for="warm-'+i+'-'+j+'">Séries de aquecimento (0 a 5)</label><input id="warm-'+i+'-'+j+'" type="number" min="0" max="5" data-field="warm" data-i="'+i+'" data-j="'+j+'" value="'+e.warm+'"><label class="label" for="special-'+i+'-'+j+'">Técnica / complemento</label><input id="special-'+i+'-'+j+'" data-field="special" data-i="'+i+'" data-j="'+j+'" value="'+esc(e.special)+'"><div class="actions" style="margin-top:9px"><button class="mini" data-a="up" data-v="'+i+':'+j+'">Subir</button><button class="mini" data-a="down" data-v="'+i+':'+j+'">Descer</button><button class="mini danger" data-a="remove" data-v="'+i+':'+j+'">Remover</button></div></div>').join('')+'<label class="label" for="addSearch'+i+'">Buscar exercício</label><input id="addSearch'+i+'" data-editor-search="'+i+'" type="search" placeholder="Nome, músculo ou equipamento"><label class="label" for="add'+i+'">Selecionar exercício</label><select id="add'+i+'">'+editorOptions('')+'</select><div class="actions" style="margin-top:8px"><button class="btn" data-a="add" data-v="'+i+'">Adicionar</button><button class="btn danger" data-a="removeday" data-v="'+i+'">Remover dia</button></div></details>').join('')+'<div class="actions editor-footer"><button class="btn" data-a="addday">Adicionar dia</button><button class="btn primary" data-a="saveplan">Salvar plano</button><button class="btn" data-a="cancel">Cancelar</button></div></section>'}
function library(){return '<h1>Exercícios</h1><p class="explain">Busque pelo nome ou pelo músculo. Consulte a execução, o equipamento e as alternativas.</p><div class="lib-filters"><div><label class="label" for="filter">Buscar exercício</label><input id="filter" type="search" placeholder="Nome, músculo ou equipamento" value="'+esc(filter)+'"></div><div><label class="label" for="kind">Tipo de treino</label><select id="kind"><option value="todos">Todos</option><option value="academia" '+(kind==='academia'?'selected':'')+'>Academia</option><option value="casa" '+(kind==='casa'?'selected':'')+'>Calistenia</option></select></div></div><div id="lib">'+libitems()+'</div>'}
function libitems(){let a=E.filter(e=>(kind==='todos'||e.mode===kind)&&norm(e.name+' '+e.muscle+' '+e.equip+' '+e.alt).includes(norm(filter)));if(!a.length)return '<div class="empty-state"><h3>Nenhum exercício encontrado</h3><p>Tente outro nome ou selecione todos os tipos.</p><button class="btn" data-a="clearfilter">Limpar filtros</button></div>';return '<small>'+a.length+' exercícios</small><div class="libgrid" style="margin-top:10px">'+a.sort((x,y)=>x.name.localeCompare(y.name,'pt-BR')).map(e=>'<article class="libcard"><div class="thumb">'+thumb(e)+'</div><div class="copy"><h3>'+esc(e.name)+'</h3><small>'+esc(e.muscle)+' · '+esc(e.equip)+'</small><button class="btn" data-a="libdetail" data-v="'+e.id+'">Ver exercício</button></div></article>').join('')+'</div>'+(detail===null?'':'<section class="panel details" id="libdetail"><div class="section"><h2>'+esc(E[detail].name)+'</h2><button class="mini" data-a="closelib">Fechar</button></div>'+details(E[detail])+'</section>')}


let chatBusy={treino:false,nutri:false},chatError={treino:'',nutri:''},aiStatus=null,chatDraft={treino:'',nutri:''},privacyOpen={treino:false,nutri:false};
const getMode=()=>S.tab==='food'?'nutri':'treino',isChat=()=>['coach','food'].includes(S.tab);
const chatSVG=(kind)=>'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+(kind==='nutri'?'<path d="M12 8c-3-3-9-1-9 5 0 4 3 8 6 8 1.4 0 2-.7 3-.7s1.6.7 3 .7c3 0 6-4 6-8 0-6-6-8-9-5zM12 8c0-3 1.5-5 4-6"/>':kind==='plus'?'<path d="M12 5v14M5 12h14"/>':kind==='send'?'<path d="M12 19V5m-6 6 6-6 6 6"/>':'<path d="M3 9v6m4-9v12m10-12v12m4-9v6M7 12h10"/>')+'</svg>';
function statusMarkup(){return '<span class="status-dot '+(aiStatus===true?'ready':aiStatus===false?'unavailable':'')+'"></span>'+(aiStatus===null?'Conectando…':aiStatus?'IA configurada':'IA indisponível')}
function updateChatStatus(){const el=$('chatStatus');if(el)el.innerHTML=statusMarkup()}
function resizeQuestion(){let el=$('question');if(!el)return;el.style.height='44px';el.style.height=Math.min(136,Math.max(44,el.scrollHeight))+'px';let b=$('sendAIButton');if(b)b.disabled=chatBusy[getMode()]||!el.value.trim()}
function chatViewport(){if(!isChat()){document.body.classList.remove('chat-keyboard');document.documentElement.style.removeProperty('--chat-height');return}const vv=window.visualViewport,focused=document.activeElement?.id==='question',keyboard=!!(focused&&vv&&window.innerHeight-vv.height>100);document.body.classList.toggle('chat-keyboard',keyboard);if(vv&&keyboard)document.documentElement.style.setProperty('--chat-height',Math.round(vv.height)+'px');else document.documentElement.style.removeProperty('--chat-height')}
function scrollChat(){const thread=$('chatThread');if(thread)thread.scrollTop=thread.scrollHeight}
function afterChatRender(){if(!isChat())return;resizeQuestion();chatViewport();scrollChat()}
function aiPlan(p,mode,index){if(!p)return '';return '<div class="ai-plan"><strong>Ficha sugerida · '+esc(p.name)+'</strong><p>'+p.days.length+' dias · '+p.days.reduce((n,d)=>n+d.ex.reduce((a,e)=>a+e.sets,0),0)+' séries. Revise antes de salvar.</p>'+p.days.map(d=>'<details><summary>'+esc(d.name)+' — '+esc(d.title)+'</summary><p>'+d.ex.map(e=>esc(E[e.id]?.name||'Exercício')+' · '+e.sets+' × '+esc(e.reps)+' · '+e.rest+'s · RIR '+esc(e.rir)).join('<br>')+'</p></details>').join('')+'<button class="btn primary" style="width:100%;margin-top:10px" data-ai="save" data-mode="'+mode+'" data-index="'+index+'">Abrir no editor de treinos</button></div>'}

function coach(food=false){const mode=food?'nutri':'treino',history=S.chat[mode]||[],name=food?'IA de nutrição':'IA de treino',heading=food?'O que você quer organizar?':'O que vamos ajustar no treino?',intro=food?'Converse sobre refeições, cardápios, preferências e objetivos. Receba sugestões adaptadas à sua rotina.':'Conte sua experiência, tempo disponível e equipamentos. Posso montar uma ficha, explicar exercícios ou ajudar a adaptar seu treino.',prompts=food?['Cardápio para ganhar massa','Refeições práticas e econômicas','Organizar minha alimentação','Sugestões de substituições']:['Criar treino de academia','Começar na calistenia','Treino de glúteos e pernas','Adaptar minha ficha'];return '<div class="chat-shell"><header class="chat-head"><div class="chat-avatar">'+chatSVG(mode)+'</div><div class="chat-heading"><h1>'+name+'</h1><div class="chat-status" id="chatStatus">'+statusMarkup()+'</div></div><button class="new-chat" data-ai="clear" aria-label="Nova conversa" title="Nova conversa">'+chatSVG('plus')+'<span>Nova conversa</span></button></header><section class="chat-thread" id="chatThread" aria-label="Mensagens" aria-live="polite">'+(!history.length&&!chatBusy[mode]?'<div class="chat-welcome"><h2>'+heading+'</h2><p>'+intro+'</p><div class="chips">'+prompts.map(q=>'<button data-ai="suggest" data-v="'+esc(q)+'">'+esc(q)+'<span aria-hidden="true"></span></button>').join('')+'</div></div>':history.map((m,i)=>'<article class="bubble '+(m.user?'user':'')+'"><small>'+(m.user?'Você':m.source==='ai'?'Traincore · IA':'Traincore · guia anterior')+'</small><div class="message-text">'+esc(m.text)+'</div>'+(m.plan&&mode==='treino'?aiPlan(m.plan,mode,i):'')+(!m.user?'<button class="chat-message-copy" data-ai="copy" data-index="'+i+'">Copiar resposta</button>':'')+'</article>').join(''))+(chatBusy[mode]?'<div class="bubble" role="status"><small>Traincore · IA</small><span class="chat-loading" aria-label="Preparando resposta"><i></i><i></i><i></i></span> Preparando resposta…</div>':'')+'</section><div class="chat-composer"><div class="chat-consent" id="chatConsentPanel" '+(S.aiConsent&&!privacyOpen[mode]?'hidden':'')+'><label><input type="checkbox" id="aiConsent" '+(S.aiConsent?'checked':'')+'> Autorizo o envio das minhas mensagens ao provedor de IA.</label><p>Evite dados pessoais e informações médicas sensíveis. Você pode alterar esta opção em Privacidade.</p></div><div class="chat-error" role="alert">'+esc(chatError[mode])+'</div><div class="chat-inputbox"><label class="sr-only" for="question">Sua mensagem</label><textarea id="question" rows="1" maxlength="3000" placeholder="'+(food?'Pergunte sobre alimentação…':'Pergunte sobre seu treino…')+'">'+esc(chatDraft[mode])+'</textarea><button class="chat-send" id="sendAIButton" data-ai="send" aria-label="Enviar mensagem" title="Enviar mensagem" '+(chatBusy[mode]||!chatDraft[mode].trim()?'disabled':'')+'>'+chatSVG('send')+'</button></div><div class="chat-meta"><span>'+(food?'IA educativa; não substitui nutricionista.':'IA educativa; revise as recomendações.')+'</span><button data-ai="privacy" aria-expanded="'+(!S.aiConsent||privacyOpen[mode])+'">Privacidade</button></div></div></div>'}
async function sendAI(){const mode=getMode();if(chatBusy[mode])return;const input=$('question'),q=input?.value.trim();if(!q)return;if(!S.aiConsent){chatError[mode]='Autorize o envio das mensagens para continuar.';privacyOpen[mode]=true;render();return}const history=S.chat[mode]||[];S.chat[mode]=history;chatError[mode]='';history.push({user:true,text:q,source:'ai'});chatDraft[mode]='';chatBusy[mode]=true;render();try{let context=history.filter(m=>m.source==='ai').slice(-14).map(m=>({role:m.user?'user':'assistant',content:m.text.slice(0,5000)}));while(context.reduce((n,m)=>n+m.content.length,0)>23000)context.shift();let res=await fetch('/api/forma-chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,messages:context}),signal:typeof AbortSignal.timeout==='function'?AbortSignal.timeout(55000):undefined});let o;try{o=await res.json()}catch{throw Error('O servidor não retornou uma resposta válida.')}if(!res.ok)throw Error(o.error||'A IA está indisponível.');if(typeof o.reply!=='string'||!o.reply.trim())throw Error('Resposta vazia. Tente novamente.');let plan=null;if(o.planInvalid)chatError[mode]='A resposta foi recebida, mas a ficha estruturada não passou na validação. Peça para a IA gerar novamente.';if(mode==='treino'&&o.plan){try{const p=unpack([1,o.plan.name,o.plan.days.map(d=>[d.name,d.title,d.warm,d.cardio,d.ex.map(e=>fields.map(f=>e[f]))])]);plan={name:p.name,days:p.days}}catch{}}if(S.chat[mode]===history)history.push({user:false,text:o.reply,source:'ai',plan});aiStatus=true}catch(e){chatError[mode]=e.name==='TimeoutError'?'A resposta demorou mais que o esperado. Sua mensagem foi mantida; tente novamente.':e.message||'Não foi possível conectar à IA.';if(S.chat[mode]===history&&history.at(-1)?.user)history.pop();if(!chatDraft[mode])chatDraft[mode]=q}finally{chatBusy[mode]=false;save();if(isChat()&&getMode()===mode)render()}}
document.addEventListener('click',ev=>{let b=ev.target.closest('[data-ai]');if(!b)return;let a=b.dataset.ai,mode=getMode();if(a==='suggest'){chatDraft[mode]=b.dataset.v;$('question').value=b.dataset.v;resizeQuestion();$('question').focus()}else if(a==='send')sendAI();else if(a==='copy'){let m=S.chat[mode]?.[+b.dataset.index];if(m)navigator.clipboard?.writeText(m.text).then(()=>toast('Resposta copiada.')).catch(()=>toast('Não foi possível copiar automaticamente.'));}else if(a==='privacy'){privacyOpen[mode]=!privacyOpen[mode];const panel=$('chatConsentPanel');panel.hidden=S.aiConsent&&!privacyOpen[mode];b.setAttribute('aria-expanded',String(!panel.hidden));}else if(a==='clear'){if(chatBusy[mode])return;if(!S.chat[mode]?.length||confirm('Iniciar nova conversa? O histórico deste assistente será apagado neste aparelho.')){S.chat[mode]=[];chatDraft[mode]='';chatError[mode]='';render(false)}}else if(a==='save'){let m=S.chat[b.dataset.mode]?.[+b.dataset.index];if(!m?.plan)return;if(draft&&!confirm('Substituir o rascunho que está aberto?'))return;draft={...copy(m.plan),id:uid()};S.tab='plans';render(false);$('builder')?.scrollIntoView({block:'start'})}});
document.addEventListener('input',ev=>{if(ev.target.id==='question'){chatDraft[getMode()]=ev.target.value;resizeQuestion()}});
document.addEventListener('change',ev=>{if(ev.target.id==='aiConsent'){S.aiConsent=ev.target.checked;save();if(S.aiConsent){privacyOpen[getMode()]=false;$('chatConsentPanel').hidden=true;const b=document.querySelector('[data-ai="privacy"]');b?.setAttribute('aria-expanded','false');chatError[getMode()]='';document.querySelector('.chat-error').textContent=''}}});
document.addEventListener('keydown',ev=>{if(ev.target.id==='question'&&ev.key==='Enter'&&!ev.shiftKey&&!ev.isComposing&&!matchMedia('(pointer:coarse)').matches){ev.preventDefault();sendAI()}});
document.addEventListener('focusin',ev=>{if(ev.target.id==='question')chatViewport()});document.addEventListener('focusout',ev=>{if(ev.target.id==='question')requestAnimationFrame(chatViewport)});window.visualViewport?.addEventListener('resize',chatViewport);window.addEventListener('resize',chatViewport);
fetch('/api/forma-chat',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject()).then(o=>{aiStatus=o.configured===true;updateChatStatus()}).catch(()=>{aiStatus=false;updateChatStatus()});
function render(keep=true){let y=scrollY,wasOpen=savedOpen();document.body.dataset.page=S.tab;document.body.classList.toggle('chat-mode',isChat()); $('pageContext').textContent=({home:'Hoje',train:'Treino',plans:'Meus planos',library:'Exercícios',coach:'Assistente de treino',food:'Nutrição'})[S.tab]||'Hoje'; $('nav').innerHTML=tabs.map(([k,n])=>'<button data-a="tab" data-v="'+k+'" class="'+(S.tab===k?'active':'')+'" '+(S.tab===k?'aria-current="page"':'')+'><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="'+symbols[k]+'"/></svg>'+n+'</button>').join('');$('view').innerHTML=({home,train,plans,library,coach:()=>coach(false),food:()=>coach(true)}[S.tab]||home)()+(!store?'<p class="danger">Armazenamento local indisponível neste navegador.</p>':'');if(keep)document.querySelectorAll('details[data-persist-open]').forEach(el=>{if(wasOpen.includes(el.dataset.persistOpen))el.open=true;else if(el.dataset.persistOpen.startsWith('editor:')&&wasOpen.some(k=>k.startsWith('editor:')))el.open=false});save();scrollTo(0,isChat()?0:keep?y:0);if(isChat())afterChatRender();else chatViewport();paintRest()}
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6),copy=x=>JSON.parse(JSON.stringify(x)),emptyday=i=>({name:['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'][i]||'Dia '+(i+1),title:'Treino '+(i+1),warm:'5 min leves + séries preparatórias',cardio:'',ex:[]});

let restRun=null;
function remaining(t,now=Date.now()){return t.paused?Math.max(0,t.left):Math.max(0,Math.ceil((t.deadline-now)/1000))}
function persistRest(){S.restTimer=restRun?{...restRun}:null;save()}
function paintRest(){const t=restRun,visible=!!t;document.body.classList.toggle('has-rest-timer',visible);$('timer').classList.toggle('show',visible);if(t){const n=remaining(t);$('clock').textContent=restFormat(n);$('timerExercise').textContent=t.name||'Descanso do treino';$('timerStatus').textContent=n===0?'Descanso concluído':t.paused?'Descanso pausado':t.kind||'Descanso entre séries';$('timerTarget').textContent='Intervalo: '+restWords(t.total);$('timerFill').style.width=(t.total?Math.min(100,n/t.total*100):0)+'%';$('timerDone').hidden=n!==0;$('pause').textContent=t.paused?'Retomar':'Pausar';$('pause').disabled=n===0;$('minus').disabled=n===0;$('plus').disabled=false}
document.querySelectorAll('[data-rest-key]').forEach(el=>{const match=t&&el.dataset.restKey===t.owner,btn=el.querySelector('[data-a="timer"]'),v=el.querySelector('[data-rest-value]'),st=el.querySelector('[data-rest-state]');const n=match?remaining(t):Number(btn.dataset.v);v.textContent=restFormat(n);el.classList.toggle('running',!!match&&n>0);el.classList.toggle('finished',!!match&&n===0);st.textContent=match?(n===0?'Concluído':t.paused?'Pausado':'Tempo restante'):'Tempo previsto';btn.textContent=match&&n>0?'Reiniciar cronômetro de descanso':'Iniciar cronômetro de descanso'})}
function tick(){if(!restRun)return;let n=remaining(restRun);if(n===0&&!restRun.completed){restRun.completed=true;restRun.paused=false;restRun.left=0;clearInterval(timerId);persistRest();try{navigator.vibrate?.([150,80,150])}catch{}}paintRest()}
function runTicker(){clearInterval(timerId);if(restRun&&!restRun.paused&&remaining(restRun)>0)timerId=setInterval(tick,250);tick()}
function start(sec,name='Descanso do treino',owner='',kind='Descanso entre séries'){sec=Math.max(1,Math.min(3600,Math.ceil(Number(sec)||0)));restRun={total:sec,left:sec,deadline:Date.now()+sec*1000,paused:false,completed:false,name:String(name).slice(0,160),owner:String(owner),kind:String(kind)};persistRest();runTicker()}
function stopRest(){clearInterval(timerId);restRun=null;persistRest();paintRest()}
function changeRest(delta){if(!restRun)return;const n=remaining(restRun);const next=Math.max(0,Math.min(3600,n+delta));restRun.total=Math.max(next,Math.min(3600,restRun.total+delta));restRun.left=next;restRun.deadline=Date.now()+next*1000;restRun.completed=false;if(next>0&&n===0)restRun.paused=false;persistRest();runTicker()}
$('pause').onclick=()=>{if(!restRun||remaining(restRun)===0)return;const n=remaining(restRun);restRun.paused=!restRun.paused;restRun.left=n;restRun.deadline=Date.now()+n*1000;persistRest();runTicker()};$('plus').onclick=()=>changeRest(15);$('minus').onclick=()=>changeRest(-15);$('end').onclick=stopRest;
if(S.restTimer&&Number.isFinite(S.restTimer.deadline)&&Number.isFinite(S.restTimer.total)&&Number.isFinite(S.restTimer.left)&&S.restTimer.total>0){restRun={...S.restTimer};runTicker()}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&restRun)tick()});
document.addEventListener('change',ev=>{if(ev.target.id==='autoRest'){S.autoRest=ev.target.checked;save()}});
document.addEventListener('input',e=>{let t=e.target;if(t.id==='workoutSearch'){let count=0;document.querySelectorAll('#workoutIndexList .workout-jump').forEach(b=>{b.hidden=!b.dataset.search.includes(norm(t.value));if(!b.hidden)count++});$('workoutNoResults').hidden=count>0;return}if(t.dataset.editorSearch!==undefined){const select=$('add'+t.dataset.editorSearch);if(select)select.innerHTML=editorOptions(t.value);return}if(t.dataset.logKey&&t.dataset.logField){let entry=S.entries[t.dataset.logKey]||{};entry[t.dataset.logField]=t.value;S.entries[t.dataset.logKey]=entry;save()}if(t.id==='notes'){S.notes[active().id+':'+S.day]=t.value;save()}if(t.id==='filter'){filter=t.value;$('lib').innerHTML=libitems()}if(t.id==='pname'&&draft){draft.name=t.value;save()}if(t.dataset.field&&draft){let d=draft.days[+t.dataset.i],f=t.dataset.field;if(f==='daytitle')d.title=t.value;else if(t.dataset.j===undefined)d[f]=t.value;else{let x=d.ex[+t.dataset.j];x[f]=['sets','rest','warm'].includes(f)?+t.value:t.value}save()}});document.addEventListener('change',e=>{if(e.target.id==='kind'){kind=e.target.value;$('lib').innerHTML=libitems()}});
document.addEventListener('click',ev=>{let b=ev.target.closest('[data-a]');if(!b)return;let a=b.dataset.a,v=b.dataset.v,p=active(),d=p.days[S.day],i,j; if(a==='jump-ex'){document.getElementById('workout-ex-'+Number(v))?.scrollIntoView({block:'start'});return}if(a==='backup'){dataDownload();return}if(a==='restore'){$('restoreFile')?.click();return}if(a==='clearfilter'){filter='';kind='todos';detail=null;render();return}if(a==='tab'){S.tab=v;render(false);return}if(a==='timer'){start(+v,b.dataset.restName||'Descanso do treino',b.dataset.restOwner||'',b.dataset.restKind||'Descanso entre séries');return}if(a==='motion'){let m=b.closest('.details')?.querySelector('.media');if(m){let on=m.classList.toggle('playing');m.classList.toggle('paused',!on);b.textContent=on?'Pausar animação':'Reproduzir animação';b.setAttribute('aria-pressed',String(on))}return}if(a==='day'){if(!p.days[+v])return;if(S.day!==+v)stopRest();S.day=+v;S.tab='train';render(false);return}if(a==='set'){[i,j]=v.split(':').map(Number);if(!d?.ex[i]||!Number.isInteger(j)||j<0||j>=d.ex[i].sets)return;let k=key(p.id,S.day,i,j);S.checks[k]=!S.checks[k];if(S.checks[k]&&S.autoRest!==false&&d?.ex[i]&&count(p,S.day)<sum(d)){const e=d.ex[i];start(e.rest,e.name,restKey(p,S.day,i),'Descanso após a série '+(j+1))}}else if(a==='all'){i=+v;if(!d?.ex[i])return;let yes=d.ex[i].sets===Array.from({length:d.ex[i].sets},(_,s)=>checked(p.id,S.day,i,s)).filter(Boolean).length;for(let s=0;s<d.ex[i].sets;s++)S.checks[key(p.id,S.day,i,s)]=!yes}else if(a==='flag'){let k=key(p.id,S.day,v,0);S.checks[k]=!S.checks[k]}else if(a==='detail'){open.has(v)?open.delete(v):open.add(v)}else if(a==='finish'){let l={plan:p.name,day:d.name,date:date(),done:count(p,S.day),total:sum(d),id:p.id+':'+S.day+':'+date()};if(l.done<l.total&&!confirm('Registrar sessão parcial?'))return;stopRest();l.note=S.notes[p.id+':'+S.day]||'';l.exercises=d.ex.map((e,i)=>({name:e.name,total:e.sets,done:Array.from({length:e.sets},(_,j)=>checked(p.id,S.day,i,j)).filter(Boolean).length,records:Array.from({length:e.sets},(_,j)=>({set:j+1,...(S.entries[key(p.id,S.day,i,j)]||{})})).filter(r=>r.load||r.actual)}));S.logs=S.logs.filter(x=>x.id!==l.id);S.logs.push(l);S.tab='home';render(false);return}else if(a==='new'){if(draft&&!confirm('Substituir o rascunho que está aberto?'))return;draft={id:uid(),name:'Meu treino',days:[emptyday(0)]};S.tab='plans';render();$('builder').scrollIntoView();return}else if(a==='activate'){if(!S.plans.some(p=>p.id===v))return;stopRest();S.plan=v;S.day=0;S.tab='train';render(false);return}else if(a==='edit'||a==='clone'){if(draft&&!confirm('Substituir o rascunho que está aberto?'))return;let x=S.plans.find(x=>x.id===v);if(!x)return;draft=copy(x);if(a==='clone'){draft.id=uid();draft.name+=' — cópia'}S.tab='plans';render();$('builder').scrollIntoView();return}else if(a==='delete'){if(!confirm('Excluir este plano?'))return;S.plans=S.plans.filter(x=>x.id!==v);if(S.plan===v){stopRest();S.plan=S.plans[0]?.id||null;S.day=0}}else if(a==='generate'){let n=+$('freq').value,mode=$('model').value;if(draft.days.some(d=>d.ex.length)&&!confirm('Substituir os exercícios do rascunho pelo modelo?'))return;draft.days=beginnerTemplate(n,mode)}else if(a==='addday'){if(draft.days.length<7){let i=weekdays.findIndex(w=>!draft.days.some(d=>norm(d.name)===norm(w)));draft.days.push(emptyday(i<0?draft.days.length:i))}}else if(a==='removeday'){if(draft.days.length>1)draft.days.splice(+v,1)}else if(a==='add'){let selected=$('add'+v).value;if(selected===''||!E[Number(selected)])return;let e=copy(E[Number(selected)]);e.special='';e.rir='3';draft.days[+v].ex.push(e)}else if(['remove','up','down'].includes(a)){[i,j]=v.split(':').map(Number);let ex=draft.days[i].ex;if(a==='remove')ex.splice(j,1);else{let k=j+(a==='up'?-1:1);if(k>=0&&k<ex.length)[ex[j],ex[k]]=[ex[k],ex[j]]}}else if(a==='saveplan'){if(!validDraft(draft)||new Set(draft.days.map(d=>norm(d.name))).size!==draft.days.length){alert('Confira o nome, dias distintos, exercícios e valores da ficha. Use 1–10 séries, descanso de 15–600 segundos e campos completos.');return}const prev=S.plans.find(p=>p.id===draft.id),changed=prev&&planShape(prev)!==planShape(draft);if(changed&&Object.keys(S.checks).some(k=>k.includes(':'+draft.id+':')&&S.checks[k])&&!confirm('A estrutura mudou. As marcações atuais desta ficha serão reiniciadas para não associar séries ao exercício errado. O histórico já registrado será mantido. Continuar?'))return;if(changed){S.checks=Object.fromEntries(Object.entries(S.checks).filter(([k])=>!k.includes(':'+draft.id+':')));S.entries=Object.fromEntries(Object.entries(S.entries).filter(([k])=>!k.includes(':'+draft.id+':')))}S.plans=S.plans.filter(p=>p.id!==draft.id);S.plans.push(copy(draft));if(!S.plan){S.plan=draft.id;S.day=0}draft=null;toast('Treino salvo. Abra a ficha em Meus planos.')}else if(a==='cancel'){if(!confirm('Descartar este rascunho?'))return;draft=null}else if(a==='libdetail'){detail=+v;$('lib').innerHTML=libitems();$('libdetail').scrollIntoView();return}else if(a==='closelib'){let previous=detail;detail=null;$('lib').innerHTML=libitems();document.querySelector('[data-a="libdetail"][data-v="'+previous+'"]')?.focus();return}render()});

/* FORMA Share v1 — public plan data only; no user/session data. */
const shareDialog=$('shareDialog'), shareContent=$('shareContent');
let sharedCode='', importedPlan=null, shareGeneration=0;
const SHARE_MAX=100000, PAYLOAD_MAX=180000;
const fields=['id','sets','reps','rest','rir','warm','special'];
function planForShare(id){return S.plans.find(p=>p.id===id)}
function sharePayload(p){return [1,p.name,p.days.map(d=>[d.name,d.title,d.warm||'',d.cardio||'',d.ex.map(e=>fields.map(f=>e[f]??''))])]}
function b64url(bytes){let out='';for(let i=0;i<bytes.length;i+=8192)out+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(out).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function from64(s){if(!/^[A-Za-z0-9_-]+$/.test(s))throw Error('Código inválido.');return Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-s.length%4)%4)),c=>c.charCodeAt(0))}
async function readBounded(stream,limit){const reader=stream.getReader(),chunks=[];let n=0;try{for(;;){let {done,value}=await reader.read();if(done)break;n+=value.length;if(n>limit){await reader.cancel();throw Error('Ficha grande demais.')}chunks.push(value)}}finally{reader.releaseLock()}let out=new Uint8Array(n),i=0;for(let c of chunks){out.set(c,i);i+=c.length}return out}
function validText(x,max,required=false){if(typeof x!=='string'||x.length>max||(required&&!x.trim()))throw Error('A ficha contém campos inválidos ou muito longos.');return x}
function validInt(x,min,max){if(!Number.isInteger(x)||x<min||x>max)throw Error('A ficha contém séries, descansos ou exercícios inválidos.');return x}
function unpack(a){if(!Array.isArray(a)||a.length!==3||a[0]!==1||!Array.isArray(a[2])||a[2].length<1||a[2].length>7)throw Error('Formato de treino incompatível.');return {name:validText(a[1],120,true),days:a[2].map(d=>{if(!Array.isArray(d)||d.length!==5||!Array.isArray(d[4])||!d[4].length||d[4].length>40)throw Error('Dia de treino inválido.');return {name:validText(d[0],60,true),title:validText(d[1],160,true),warm:validText(d[2],2000),cardio:validText(d[3],2000),ex:d[4].map(e=>{if(!Array.isArray(e)||e.length!==7)throw Error('Exercício inválido.');const id=validInt(e[0],0,E.length-1);return {...copy(E[id]),sets:validInt(e[1],1,10),reps:validText(e[2],80,true),rest:validInt(e[3],15,600),rir:validText(e[4],80,true),warm:validInt(e[5],0,10),special:validText(e[6],3000)}})}})}}
async function encodePlan(p){const payload=sharePayload(p);unpack(payload);let bytes=new TextEncoder().encode(JSON.stringify(payload));if(bytes.length>PAYLOAD_MAX)throw Error('Ficha grande demais para compartilhamento.');let tag='T';if(typeof CompressionStream==='function'){try{let zipped=await readBounded(new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip')),PAYLOAD_MAX);if(zipped.length<bytes.length){tag='G';bytes=zipped}}catch{}}const code='FORMA1-'+tag+'-'+b64url(bytes);if(code.length>SHARE_MAX)throw Error('Código grande demais. Reduza o tamanho da ficha.');return code}
function extractCode(input){let t=input.trim();if(t.startsWith('https://')||t.startsWith('http://')){let u=new URL(t);if(!u.hash.startsWith('#treino='))throw Error('Link sem código de treino.');t=decodeURIComponent(u.hash.slice(8))}return t.replace(/\s/g,'')}
async function decodePlan(input){if(typeof input!=='string'||input.length>SHARE_MAX*2)throw Error('Código muito longo.');const code=extractCode(input);if(code.length>SHARE_MAX)throw Error('Código muito longo.');const m=/^FORMA1-([TG])-([A-Za-z0-9_-]+)$/.exec(code);if(!m)throw Error('Código inválido ou incompatível. Confira se foi copiado por inteiro.');let bytes=from64(m[2]);if(m[1]==='G'){if(typeof DecompressionStream!=='function')throw Error('Este navegador não lê códigos compactados. Use um navegador atualizado.');bytes=await readBounded(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')),PAYLOAD_MAX)}if(bytes.length>PAYLOAD_MAX)throw Error('Ficha grande demais.');return unpack(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes)))}
function shareLink(code){let u=new URL(location.href);u.search='';u.hash='treino='+encodeURIComponent(code);return u.href}
function showShare(){if(!shareDialog.open)shareDialog.showModal()}
function closeShare(){shareGeneration++;importedPlan=null;sharedCode='';if(shareDialog.open)shareDialog.close()}
async function openExport(id){const p=planForShare(id);if(!p)return;let g=++shareGeneration;importedPlan=null;sharedCode='';$('shareHeading').textContent='Compartilhar treino';shareContent.innerHTML='<p>Gerando código…</p>';showShare();try{let code=await encodePlan(p);if(g!==shareGeneration)return;sharedCode=code;shareContent.innerHTML='<h3>'+esc(p.name)+'</h3><p>'+p.days.length+' dias · '+total(p)+' séries. O código contém somente a ficha; histórico, cargas, notas e alimentação não são enviados.</p><label class="label" for="shareCode">Código de compartilhamento</label><textarea readonly id="shareCode">'+esc(code)+'</textarea><div class="actions"><button class="btn primary" data-share="copy-code">Copiar código</button><button class="btn" data-share="copy-link">Copiar link</button></div>'+(typeof navigator.share==='function'?'<button class="btn" style="width:100%;margin-top:8px" data-share="native">Enviar para outra pessoa</button>':'')+'<p class="note">Quem receber pode colar o código em Planos → Importar por código, ou abrir o link. A cópia é independente e não recebe futuras alterações.</p><p id="shareStatus" role="status"></p>'}catch(e){if(g===shareGeneration)shareContent.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}}
function openImport(input=''){shareGeneration++;sharedCode='';importedPlan=null;$('shareHeading').textContent='Importar treino';shareContent.innerHTML='<p>Cole o código ou link enviado por outra pessoa. Você poderá revisar os dias antes de salvar.</p><label class="label" for="importCode">Código ou link</label><textarea id="importCode" maxlength="200000" placeholder="FORMA1-…">'+esc(input)+'</textarea><button class="btn primary" data-share="preview" style="width:100%;margin-top:10px">Conferir ficha</button><div id="importPreview"></div><p id="shareStatus" role="alert"></p>';showShare();if(input)previewImport()}
async function previewImport(){let el=$('importCode');if(!el)return;const g=++shareGeneration;importedPlan=null;$('importPreview').innerHTML='';$('shareStatus').textContent='Conferindo…';try{let p=await decodePlan(el.value);if(g!==shareGeneration)return;importedPlan=p;$('shareStatus').textContent='';$('importPreview').innerHTML='<div class="preview"><h3>'+esc(p.name)+'</h3><p>'+p.days.length+' dias · '+total(p)+' séries · '+p.days.reduce((n,d)=>n+d.ex.length,0)+' exercícios.</p>'+p.days.map(d=>'<details class="row" style="display:block"><summary>'+esc(d.name)+' — '+esc(d.title)+' · '+sum(d)+' séries</summary><div class="import-day"><p><strong>Aquecimento:</strong> '+esc(d.warm||'Não especificado')+'</p><p><strong>Cardio:</strong> '+esc(d.cardio||'Não especificado')+'</p>'+d.ex.map(e=>'<article class="import-exercise"><div class="import-exercise-head"><div class="thumb">'+thumb(e)+'</div><div><strong>'+esc(e.name)+'</strong><p>'+e.sets+' × '+esc(e.reps)+' · descanso '+restFormat(e.rest)+'</p><small>RIR: '+esc(e.rir)+' · '+e.warm+' séries de aquecimento</small></div></div><details><summary>Instruções e demonstração</summary>'+details(e,true)+'</details></article>').join('')+'</div></details>').join('')+'<p class="note">Salve e use a ficha para iniciar os cronômetros e registrar as séries. Seus outros planos serão mantidos.</p><button class="btn primary" style="width:100%" data-share="confirm-import">Salvar e usar treino</button></div>'}catch(e){if(g===shareGeneration)$('shareStatus').textContent=e instanceof SyntaxError?'Código inválido ou incompleto.':e.message||'Não foi possível importar o treino.'}}
async function copyShare(textValue){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(textValue);return true}}catch{}const tmp=document.createElement('textarea');tmp.value=textValue;tmp.style.cssText='position:fixed;opacity:0;left:0;top:0';shareDialog.append(tmp);tmp.select();let ok=false;try{ok=document.execCommand('copy')}catch{}tmp.remove();return ok}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-share]');if(!b)return;const a=b.dataset.share;if(a==='close')return closeShare();if(a==='export')return openExport(b.dataset.id);if(a==='import')return openImport();if(a==='preview')return previewImport();if(a==='confirm-import'&&importedPlan){const p={...copy(importedPlan),id:uid()};S.plans.push(p);S.plan=p.id;S.day=0;S.tab='train';closeShare();if(location.hash.startsWith('#treino='))history.replaceState(null,'',location.pathname+location.search);render(false);return}if((a==='copy-code'||a==='copy-link')&&sharedCode){let ok=await copyShare(a==='copy-code'?sharedCode:shareLink(sharedCode));if($('shareStatus'))$('shareStatus').textContent=ok?'Copiado!':'Não foi possível copiar automaticamente. Selecione o código e copie manualmente.'}if(a==='native'&&sharedCode){try{await navigator.share({title:'Treino Traincore',text:'Importe minha ficha no Traincore.',url:shareLink(sharedCode)})}catch(e){if(e.name!=='AbortError'&&$('shareStatus'))$('shareStatus').textContent='Não foi possível abrir o compartilhamento. Use Copiar link.'}}});
shareDialog.addEventListener('close',()=>{shareGeneration++;importedPlan=null;sharedCode=''});
document.addEventListener('input',ev=>{if(ev.target.id==='importCode'){shareGeneration++;importedPlan=null;$('importPreview').innerHTML='';$('shareStatus').textContent=''}});
function openSharedHash(){if(location.hash.startsWith('#treino=')){try{openImport(decodeURIComponent(location.hash.slice(8)))}catch{openImport()}}}
window.addEventListener('hashchange',openSharedHash);

if(!S.plans.some(p=>p.id===S.plan)){S.plan=null;S.day=0}render(false);openSharedHash();initMedia();
